WITH enriched AS (SELECT *, AVG(rating) OVER (ORDER BY rating, id ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS rating_avg_6_prior, PERCENT_RANK() OVER (PARTITION BY city ORDER BY rating DESC) AS rating_percent_rank FROM suppliers) SELECT id, country, city, rating, rating_percent_rank, CASE WHEN city RLIKE '^(New York|Berlin)$' THEN 'GROUP_B' WHEN city RLIKE '^(Bangkok|Chiang Mai)$' THEN 'EXTENDED' ELSE 'GROUP_A' END AS city_zone FROM enriched ORDER BY city DESC NULLS FIRST
